CREATE DATABASE IF NOT EXISTS `db_base` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `db_base`;

--
-- Creación de las cuentas para el servidor
--

CREATE USER IF NOT EXISTS 'manager'@'%' IDENTIFIED BY 'REPLACEME_BP';
GRANT SELECT,INSERT,UPDATE,DELETE ON db_base.* TO 'manager'@'%';

CREATE USER IF NOT EXISTS 'reader'@'%' IDENTIFIED BY 'REPLACEME_GP';
GRANT SELECT ON db_game.* TO 'reader'@'%';

FLUSH PRIVILEGES;

--
-- Estructura para la tabla `cases`
--

CREATE TABLE `cases` (
  `id` int NOT NULL,
  `consulta` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `dif` int UNSIGNED NOT NULL,
  `isExam` tinyint(1) NOT NULL,
  `isSecondary` tinyint(1) NOT NULL,
  `isFinal` tinyint(1) NOT NULL,
  `data` json NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Datos para la tabla `cases`
--

INSERT INTO `cases` (`id`, `consulta`, `dif`, `isExam`, `isSecondary`, `isFinal`, `data`) VALUES
(1, 'SELECT nombre, apellidos FROM ciudadanos WHERE altura > 1.9 AND colorPelo = \"pelirrojo\"', 1, 0, 0, 0, '{\"id\": 1, \"dif\": 1, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"Color de pelo\", \"palabras\": [\"pelirrojo\"], \"descripcion\": \"Un testigo declara haber visto a un transportista <b>pelirrojo</b> parar la nave en un punto no autorizado durante el transporte.\"}, {\"titulo\": \"Altura\", \"palabras\": [\"1.9\"], \"descripcion\": \"Además se ha fijado en que medía <b>más de 1,90</b> metros de altura.\"}], \"titulo\": \"Robo de Mercancía Peligrosa\", \"resumen\": \"Se ha detectado una pérdida de mercancía peligrosa durante su transporte y necesitan saber el <b>nombre</b> y <b>apellido</b> del responsable para poder arrestarlo.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}], \"caducidad\": -1, \"secundario\": false}'),
(2, 'SELECT idTitular FROM vehiculos WHERE marca=\"LLada\" AND color = \"negro\" AND idTitular = \"1234\" OR idTitular = \"1235\" OR idTitular = \"1236\"', 1, 0, 0, 0, '{\"id\": 2, \"dif\": 1, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"Coche sospechoso\", \"palabras\": [\"negro\", \"Llada\"], \"descripcion\": \"Según la Corgo, la semana anterior a su arresto sintió que un coche la segía a todas partes, no se fijó en la matrícula, pero era un <b>coche negro de la marca Llada</b>, una marca conocida por ser la favorita de los Exukentes.\"}, {\"titulo\": \"Un ajuste de cuentas\", \"palabras\": [\"Jarfonsez\"], \"descripcion\": \"Ella admite que podría ser un ajuste de cuentas, por eso mismo, sospecha que podría ser uno de los <b>Jarfonsez</b>.\"}], \"titulo\": \"Twisted Sisters\", \"resumen\": \"Ha surgido un revuelo tras el asesinato de 3 miembros del grupo de traficantes Corgos formado por 4 hermanas. La última se encuentra en la cárcel pero quiere venganza y pide que encuentren a los asesinos.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 3}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 5}], \"caducidad\": 1, \"secundario\": false}'),
(3, 'SELECT correo FROM pingBusquedas WHERE ip = \"83.124.66.3\"', 1, 1, 0, 0, '{\"id\": 3, \"dif\": 1, \"coste\": 1, \"examen\": true, \"pistas\": [{\"titulo\": \"Phishing\", \"palabras\": [\"juanitojavanero@picklecast.com\"], \"descripcion\": \"La compañía cree que el hacker ha empleado phising para obtener acceso, ya que el empleado Juanito Javanero acaba de indicar que ha perdido el acceso a su cuenta. La empresa no ha facilitado su correo: <b>juanitojavanero@picklecast.com</b>.\"}], \"titulo\": \"Non Funkible Token\", \"resumen\": \"Han hackeado el servidor de la empresa de streaming PickleCast y han amenazado con publicar todos los datos <b>biométricos</b>, y todos los datos sensibles que tienen. Piden un rescate altísimo en cripto-monedas y han dado 24 horas para pagar. Se pide que se busque un correo del hacker, uno <b>distinto</b> al que ha usado, para ver si hay alguna forma de localizarlo.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 10, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": -3, \"condicion\": 1}, {\"efecto\": 4, \"cantidad\": -5, \"condicion\": 1}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 2}], \"caducidad\": 1, \"secundario\": false}'),
(4, 'SELECT propietario FROM asistenteVoz WHERE log LIKE \"%bomba%\"', 2, 0, 0, 0, '{\"id\": 4, \"dif\": 2, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"Palabras Clave\", \"palabras\": [\"bomba\", \"explosivo\", \"carga\"], \"descripcion\": \"Recomiendan buscar palabras clave como <b>bomba</b>,<b>explosivo</b>, o <b>carga</b>.\"}], \"titulo\": \"Smooth Criminal\", \"resumen\": \"Hay sospechas de que una serie de individuos están planeando un acto terrorista, y fuentes externas preveen que se usará algún tipo de explosivo.\", \"bounties\": [{\"efecto\": 1, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}], \"caducidad\": -1, \"secundario\": false}'),
(5, 'SELECT dniRegistrado FROM muricaGuns_armasRegistradas WHERE numeroSerie LIKE \"984%35\" AND marca = \"Luna\"', 2, 0, 0, 0, '{\"id\": 5, \"dif\": 2, \"coste\": 2, \"examen\": false, \"pistas\": [{\"titulo\": \"Información del Arma\", \"palabras\": [\"Luna\"], \"descripcion\": \"Un agente ha conseguido acceder al arma mencionada, es de la marca <b>Luna</b>.\"}, {\"titulo\": \"Información del Arma 2\", \"palabras\": [\"984\", \"35\"], \"descripcion\": \"El número de serie está borrado, pero aún se pueden ver que empieza por <b>984</b> y termina con <b>35</b>.\"}], \"titulo\": \"Yo no te pido la luna\", \"resumen\": \"Un Feriseo ha solicitado que se busque\", \"bounties\": [{\"efecto\": 1, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 1, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": -5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": false}'),
(6, '', 2, 1, 0, 0, '{\"id\": 6, \"dif\": 2, \"coste\": 1, \"examen\": true, \"pistas\": [{\"titulo\": \"Fuego Inusual\", \"palabras\": [\"alguicida\"], \"descripcion\": \"El fuego tenía un color inusual, era <b>verde</b>. Un científico asegura que dicho color se ha producido por incendiar el sulfato de cobre junto con el alcohol. El sulfato de cobre se encuentra en <b>productos alguicidas</b>, añade.\"}, {\"titulo\": \"Donuts\", \"palabras\": [\"51\"], \"descripcion\": \"Gracias a los donuts, unas cámaras pudieron ver parte de una de las matrículas, por lo que se sabe que una contenía el número <b>51</b> en medio de la matrícula.\"}], \"titulo\": \"Night of Fire\", \"resumen\": \"Unos conductores temerarios arrasan por la noche la sede de periodismo principal del EEL. Durante el acto terrorista pintan las paredes con mensajes de odio sobre cómo están discriminando a los Exukentes. También incendiaron el edificio y destrozaron el parque de delante haciendo donuts con los coches.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 2}], \"caducidad\": -1, \"secundario\": false}'),
(7, 'SELECT dni FROM ciudadanos WHERE apellido = \"Vareta\" HAVING MIN(edad)', 3, 0, 0, 0, '{\"id\": 7, \"dif\": 3, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"El arma\", \"palabras\": [\"Luna\"], \"descripcion\": \"La pistola láser es de la marca <b>Luna</b>.\"}, {\"titulo\": \"El número de serie\", \"palabras\": [\"984\", \"35\"], \"descripcion\": \"El número de serie del arma está borrado, pero se pueden distinguir que empieza por <b>984</b>, y termina en <b>35</b>.\"}], \"titulo\": \"La gata bajo la lluvia\", \"resumen\": \"Un Feriseo está pidiendo ayuda para demostrar que su mujer es inocente de uno de sus crímenes...\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 6}, {\"efecto\": 3, \"cantidad\": 10, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": -5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": false}'),
(8, 'SELECT zonaDestino FROM rutas WHERE zonaOrigen = \"wet groove\" AND fecha = \"21-04-2224\" GROUP BY zonaDestino ORDER BY COUNT(zonaDestino) desc LIMIT 1', 3, 0, 0, 0, '{\"id\": 8, \"dif\": 3, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"Fecha del evento\", \"palabras\": [\"21-04-2224\"], \"descripcion\": \"El humano dijo que la fiesta ocurrió el 21 de este mes.\"}, {\"titulo\": \"Nombre del local\", \"palabras\": [\"wet groove\"], \"descripcion\": \"El local en el que se hizo la fiesta se llama <b>Wet Groove</b>.\"}, {\"titulo\": \"La puerta\", \"palabras\": [\"---\"], \"descripcion\": \"Tras llegar al establecimiento, los agentes descubrieron que la misteriosa puerta \"}], \"titulo\": \"Me colé en una fiesta\", \"resumen\": \"Pepuv quiere que encuentres el lugar al que más coches fueron después del incidente de la fiesta.\", \"bounties\": [{\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 2, \"condicion\": 3}, {\"efecto\": 4, \"cantidad\": -15, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}], \"caducidad\": -1, \"secundario\": false}'),
(9, 'SELECT numPuerto, entidadSolicitante, COUNT(fechaLlegada) AS veces FROM transbordos WHERE numpuerto BETWEEN 4 AND 8 GROUP BY numpuerto, entidadsolicitante HAVING veces >= 40', 3, 1, 0, 0, '{\"id\": 9, \"dif\": 3, \"coste\": 0, \"examen\": true, \"pistas\": [{\"titulo\": \"Rango de puertos\", \"palabras\": [\"4\", \"8\"], \"descripcion\": \"Según pepuv, las operaciones sospechosas ocurren del puerto 4 al 8.\"}, {\"titulo\": \"Cantidad extrema de Transbordos\", \"palabras\": [\"40\"], \"descripcion\": \"Sólo interesan aquellas empresas que superen los 40 transbordos en cada puerto.\"}], \"titulo\": \"Deja Vu\", \"resumen\": \"Pepuv continuó investigando el caso anterior y ha encontrado algo sospechoso en los Transbordos de la bahía del EEL. Pide explícitamente una lista de la cantidad de transbordos hechos por cada empresa (entidadSolicitante) en cada puerto.\", \"bounties\": [{\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 10, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 3}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 5}], \"caducidad\": -1, \"secundario\": false}'),
(10, 'SELECT * FROM corgomatic WHERE matricula IN(SELECT matricula FROM vehiculos WHERE titular_id IN(1,2,3,4,5,6,7,8))', 4, 0, 0, 0, '{\"id\": 10, \"dif\": 4, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Lista de matrículas\", \"palabras\": [\"1\", \"2\", \"3\", \"4\", \"5\", \"6\", \"7\"], \"descripcion\": \"El papel que te ha dado Kevin contiene una lista de matrículas de vehículos.\"}], \"titulo\": \"Just The Two of Us\", \"resumen\": \"Un supuesto detective independiente llamado Kevin solicita que colabores con él, pide que le muestres los cambios realizados en los vehículos de una lista de personas. Es necesario la matrícula, las fechas, y la descripción de los cambios.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 3}, {\"efecto\": 0, \"cantidad\": -1, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": false}'),
(11, 'SELECT nombre, apellidos FROM ciudadanos WHERE dni IN(SELECT dni_empleado FROM transbordos_empleados WHERE transbordo IN (SELECT id FROM transbordos WHERE fechaLlegada BETWEEN \"18-03-2224\" AND \"24-04-2224\"))', 4, 0, 0, 0, '{\"id\": 11, \"dif\": 4, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Intervalo\", \"palabras\": [\"18-03-2224\", \"24-04-2224\"], \"descripcion\": \"Kevin dijo que Pepuv le mostró un rastro de sucesos que ocurrieron en la zona de transbordos entre el 18-03-2224 y el 24-04-2224.\"}], \"titulo\": \"Gangsta Paradise\", \"resumen\": \"Kevin ha descubierto una red de tráfico ilegal, pero hay algo que se le escapa de las manos, te pide que le devuelvas una lista con nombre y apellidos de cada funcionario que haya realizado una recogida de mercancía en la bahía de transbordos\", \"bounties\": [{\"efecto\": 1, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": false}'),
(12, 'SELECT dni FROM ciudadanos WHERE dni IN(???) AND raza IN(\"corgo\",\"exukente\")', 4, 1, 0, 0, '{\"id\": 12, \"dif\": 4, \"coste\": 2, \"examen\": true, \"pistas\": [{\"titulo\": \"Establecimiento\", \"palabras\": [\"---\"], \"descripcion\": \"El restaurante se llama <b>Rincón del Turro</b>\"}, {\"titulo\": \"Grabaciones\", \"palabras\": [\"---\"], \"descripcion\": \"Tus agentes que acompañaron a Kevin pudieron recuperar la grabadora, han pasado su contenido a texto y lo han mteido en la nueva tabla <b>GrabacionesRestaurante</b>.\"}], \"titulo\": \"Limón y Sal\", \"resumen\": \"Kevin ha colocado un micro oculto en el restaurante Rincón del Turro para espiar a la gente y confirmar si hablan de algo sospechoso. Quiere que descubras el dni de aquellos que tienen acceso a la zona secreta del restaurante.\", \"bounties\": [{\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 5}, {\"efecto\": 0, \"cantidad\": 2, \"condicion\": 6}, {\"efecto\": 4, \"cantidad\": 15, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": -5, \"condicion\": 1}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": false}'),
(13, 'SELECT R1.matricula FROM rutas as R1 INNER JOIN rutas AS R2 ON R1.zonaDestino = R2.zonaOrigen WHERE R1.matricula = R2.matricula AND R1.fecha = R2.fecha AND R1.zonaOrigen = \"D.M. 14\" AND R1.zonaDestino = \"Rincon del Turro\"', 5, 0, 0, 0, '{\"id\": 13, \"dif\": 5, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Parada intermedia\", \"palabras\": [\"Rincón del Turro\"], \"descripcion\": \"El <b>Rincón del Turro</b>, supuestamente un punto intermedio de recogida para el tráfico del mercado negro.\"}, {\"titulo\": \"Salida de los sospechosos\", \"palabras\": [\"D.P. 14\"], \"descripcion\": \"El Distrito de Producción 14 suele tener poca vigilancia por estar mayormente en desuso. No para el mercado negro aparentemente.\"}], \"titulo\": \"The step bellow hell\", \"resumen\": \"Kevin te pregunta si le puedes hacer una lista de los vehículo que vayan desde el distrito “D.P. 14” y que hagan una parada por el Rincón del Turro. Concretamente quiere saber las matrículas y el lugar de destino al que van tras parar en dicho establecimiento.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": -1, \"condicion\": 1}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 3}], \"caducidad\": -1, \"secundario\": false}'),
(14, 'SELECT nombre, apellido FROM ciudadanos WHERE dni = ( SELECT titular FROM viviendas AS V INNER JOIN ciudadanos as C ON V.titular = C.dni WHERE direccion LIKE \"%Kroxik Takep 31th%\" AND titular IN( SELECT propietario FROM vehiculos WHERE matricula IN( SELECT C.matricula FROM corgomatic AS C INNER JOIN rutas AS R ON C.matricula = R.matricula WHERE C.fecha = R.fecha AND C.fecha = \"28-03-2224\" AND zonaOrigen = \"Corgomatic\" ) ) )', 5, 0, 0, 0, '{\"id\": 14, \"dif\": 5, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Fecha de la persecución\", \"palabras\": [\"28-03-2224\"], \"descripcion\": \"Kevin siguió el coche sospechoso el 28-03-2224.\"}, {\"titulo\": \"Modificación del vehículo\", \"palabras\": [\"---\"], \"descripcion\": \"El coche entró en el taller mecánico de coches \\\"Corgomatic\\\"\"}, {\"titulo\": \"Punto de encuentro sospechoso\", \"palabras\": [\"Kroxik Takep 31th\"], \"descripcion\": \"¿Por qué un humano iría a aliarse con una mafia exukente? En cualquier caso, sabemos que será en la calle Kroxik Takep 31th\"}], \"titulo\": \"Scourge of the Universe\", \"resumen\": \"Gracias a ti, Kevin ha podido observar más cerca que nunca los movimientos de la sospechosa mafia \\\"La Colmena\\\". Además de la posible localización de una persona importante en la mafia, se sospecha que están aliados paradógicamente con un humano. Los datos que ha conseguido no son muy conexos pero quizás tú puedes darle un sentido y sacar un nombre en claro, nombre y apellidos para ser más precisos.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": -2, \"condicion\": 1}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 3}], \"caducidad\": -1, \"secundario\": false}'),
(15, '', 5, 0, 0, 1, '{\"id\": 15, \"dif\": 5, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"El trozo de papel\", \"palabras\": [\"vikalkontrov@antmsg.exu\"], \"descripcion\": \"Aquí hay escrito un correo electrónico: vikalkontrov@antmsg.exu\"}], \"titulo\": \"Hijo de la Luna\", \"resumen\": \"¿La realeza Exukente estaba metida en esto? Kripo parece estar muy nervioso. Tanto que se le cayó la torre de informes que llevaba. Hay un papel que olvidó recoger, tiene un correo...\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 8}], \"caducidad\": -1, \"secundario\": false}'),
(100, 'SELECT numPuerto FROM transbordos WHERE fechaLlegada = \"18-04-2224\" AND entidadSolicitante = \"Nidolé\"', 1, 0, 1, 0, '{\"id\": 100, \"dif\": 1, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Mañana\", \"palabras\": [\"18-04-2224\"], \"descripcion\": \"Lo que esea que querían hacer con su padre va a ocurrir mañana en la bahía de transbordos\"}, {\"titulo\": \"La nave objetivo\", \"palabras\": [\"Nidolé\"], \"descripcion\": \"La nave que desembarca pertenece a Nidolé, una famosa megacorporación humana de alimentos procesados\"}], \"titulo\": \"It’s my party (and i cry if i want to)\", \"resumen\": \"Un niño feriseo se ha colado en la oficina llorando? Debería indicarle a la policía el número de puerto en el que se harán las operaciones.\", \"bounties\": [{\"efecto\": 1, \"cantidad\": 1, \"condicion\": 8}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -15, \"condicion\": 1}, {\"efecto\": 4, \"cantidad\": -10, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 10, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": true}'),
(101, 'SELECT matricula, fecha FROM rutas WHERE distancia > 50.0 AND zonaOrigen = \"Avenida Reina Forilisia\" OR zonaOrigen = \"Plaza Ojo de Chlungus\" OR zonaOrigen = \"Calle Giripimbas 3º\"', 1, 0, 1, 0, '{\"id\": 101, \"dif\": 1, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Desplazamiento largo\", \"palabras\": [\"50\"], \"descripcion\": \"50 kilómetros es un viaje bastante largo. Prácticamente abarca toda la longitud de la EEL.\"}, {\"titulo\": \"Calles residenciales\", \"palabras\": [\"Avenida Reina Forilisia\", \"Plaza Ojo de Chlungus\", \"Calle Giripimbas 3º\"], \"descripcion\": \"La empresa ha indicado 3 calles residenciales como origen de los desplazamientos. Estas calles son \\\"<b>Avenida Reina Forilisia</b>\\\", \\\"<b>Plaza Ojo de Chlungus</b>\\\" y \\\"<b>Calle Giripimbas 3º</b>\\\". Todas pertenecen a la parte de la \\\"cola\\\" (trasera) del EEL.\"}], \"titulo\": \"Life is a Highway\", \"resumen\": \"Una empresa nueva de servicios ha solicitado una lista con la matrícula y la fecha de los viajes que hayan tomado más de 50 kilómetros en recorrerse.\", \"bounties\": [{\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 3, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 10, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": -5, \"condicion\": 1}], \"caducidad\": -1, \"secundario\": true}'),
(102, 'SELECT idTitular FROM vehiculos WHERE matricula = \"1234ABC\"', 2, 0, 1, 0, '{\"id\": 102, \"dif\": 2, \"coste\": 2, \"examen\": false, \"pistas\": [{\"titulo\": \"Fecha del vandalismo\", \"palabras\": [\"16-04-2224\"], \"descripcion\": \"Ocurrió el día <b>16-04-2224</b>.\"}, {\"titulo\": \"El vehículo de huída\", \"palabras\": [\"verde oscura metalizada\", \"3.5\"], \"descripcion\": \"Nadie ha visto quién o quienes han sido, pero los agentes han encontrado algunos testigos que comentaron que el vehículo de huida usado tenía <b>pintura verde oscura metalizada</b> y tendría que medie menos de <b>3,5 metros de largo</b>.\"}, {\"titulo\": \"Vehículo dañado\", \"palabras\": [\"ruedas traseras\", \"luna trasera\"], \"descripcion\": \"La policía llegó tarde aquella noche, pero consiguieron disparar a las <b>ruedas traseras y la luna trasera</b>.\"}], \"titulo\": \"Greased Lightning\", \"resumen\": \"Han anunciado el robo de unas decoraciones en un bar, los artefactos robados se consideran parte de la cultura Ferisea y estaban protegidos por el gobierno. El valor que tienen es histórico por lo que es considerado un acto puramente de vandalismo. Se busca el <b>dni</b> de algún culpable.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 10, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 2, \"condicion\": 3}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 6}], \"caducidad\": -1, \"secundario\": true}'),
(103, 'SELECT idCliente FROM MegaMilky_ventas WHERE idProducto = 100 AND fecha <= \"17-04-2224\"', 2, 0, 1, 0, '{\"id\": 103, \"dif\": 2, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"Fecha del vandalismo\", \"palabras\": [\"17-04-2224\"], \"descripcion\": \"Se sabe que el grafiti se hizo la noche del <b>17-04-2224</b>.\"}, {\"titulo\": \"Papeleras cercanas\", \"palabras\": [\"Dooburu\"], \"descripcion\": \"Nuestros agentes encontraron en papeleras cercanas a lo ocurrido, <b><i>muchas</i></b> latas de grafiti vacías de la marca \\\"<b>Dooburu</b>\\\".\"}], \"titulo\": \"Pest of the Cosmos\", \"resumen\": \"Unos vándalos dibujaron un grafiti despectivo en un edificio de una empresa de Exukentes, bajo el grafiti se puede leer que han escrito \\\"La peste del cosmos\\\". Sería de utilidad para la policía encontrar algún sospechoso relacionado(dni).\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 4, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 3}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 5}], \"caducidad\": -1, \"secundario\": true}'),
(104, 'SELECT propietario FROM AsistenteVoz WHERE id = 123', 2, 0, 1, 0, '{\"id\": 104, \"dif\": 2, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"La última compra\", \"palabras\": [\"14-04-2224\"], \"descripcion\": \"La última vez que vió al marido fue el día <b>14-04-2224</b>, le dijo que iba al <b>supermercado</b> pero no volvió\"}, {\"titulo\": \"Datos del marido\", \"palabras\": [\"434071\"], \"descripcion\": \"\\\"Es muy bueno, y llevan 20 años casados\\\". Es ingeniero. No tiene amigos Corgos. Su dni es el <b>434071</b>.\"}, {\"titulo\": \"La llamada\", \"palabras\": [], \"descripcion\": \"En la llamada su marido le dice que está de viaje con unos amigos corgos a pesar de no haber avisado antes...\"}], \"titulo\": \"I just called to say i love you\", \"resumen\": \"Una mujer Ferisea aparece en la puerta de tu despacho junto con sus 5 hijos (?!). Ha venido corriendo a las oficinas porque recibió una llamada sospechosa del marido después de no saber nada de él en varios días y la policía no parece tener especial interés en ayudarla.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 2, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 2}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 4}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 5}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 6}, {\"efecto\": 3, \"cantidad\": 100, \"condicion\": 7}], \"caducidad\": -1, \"secundario\": true}'),
(105, '', 3, 0, 1, 0, '{}'),
(106, '', 3, 0, 1, 0, '{}'),
(107, 'SELECT proveedor FROM paulsPizzeria_inventario WHERE tipo = \"animatrónico\" limit 1', 4, 0, 1, 0, '{\"id\": 107, \"dif\": 4, \"coste\": 1, \"examen\": false, \"pistas\": [{\"titulo\": \"El fundador\", \"palabras\": [\"Mailliw Afton\"], \"descripcion\": \"Se conoce que a parte de él y otros guardias anteriores, la única persona que ha trabajado allí es el fundador del establecimiento <b>Mailliw Afton</b>, pero se supone que debería estar muerto.\"}, {\"titulo\": \"El testimonio\", \"palabras\": [], \"descripcion\": \"Se interrogó al guardia de seguridad, el cual parece estar incómo hablando sobre el tema, pero menciona que le ha resultado extraño que a veces haya visto un animatrónico diferente al resto. Quizás el crador de los animatrónicos tengan algo que ver…\"}], \"titulo\": \"Join Us for a Bite\", \"resumen\": \"Ha surgido el rumor de que han estado desapareciendo niños en una pizzería familiar llamada “Paul’s Pizzeria”. El guardia de seguridad es el único testimonio que puede aclarar las cosas sobre el rumor.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 2, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": 5, \"condicion\": 0}, {\"efecto\": 3, \"cantidad\": -5, \"condicion\": 1}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 7}], \"caducidad\": -1, \"secundario\": true}'),
(108, 'SELECT objeto FROM paulsPizzeria_inventario WHERE proveedor = \"Corgomatic\" AND objeto NOT IN(\"Hernesto el Hamster\", \"Lucas el Lobo\", \"Gloria la Gallina\", \"Paul el oso Polar\")', 4, 0, 1, 0, '{\"id\": 108, \"dif\": 4, \"coste\": 0, \"examen\": false, \"pistas\": [{\"titulo\": \"Lista de animatrónicos originales\", \"palabras\": [\"Hernesto el Hamster\", \"Lucas el Lobo\", \"Gloria la Gallina\", \"Paul el oso Polar\"], \"descripcion\": \"Si hay un quinto animatrónico debería aquel que no tenga el nombre de los originales (Hernesto el Hamster, Lucas el Lobo, Gloria la Gallina y Paul el oso Polar).\"}], \"titulo\": \"Die in a Fire\", \"resumen\": \"El dueño de Corgomatic se ha presentado en tu oficina para hablarte sobre la relación que tenía con el dueño de la pizzería. Todas las señales apuntan a una sola cosa. Hay que encontrar el quinto animatrónico en el  inventario del establecimiento.\", \"bounties\": [{\"efecto\": 0, \"cantidad\": 1, \"condicion\": 0}, {\"efecto\": 1, \"cantidad\": -99, \"condicion\": 8}, {\"efecto\": 0, \"cantidad\": 1, \"condicion\": 3}], \"caducidad\": -1, \"secundario\": true}'),
(109, '', 5, 0, 1, 1, '{}');

