INSERT INTO `events` (`id`, `data`) VALUES
(0, '{·id·:0,·titulo·:·Tutorial·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·DIA_ACTUAL = 0·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - INTRO·,·HoldPause - 1·],·separador·:·Fin Dialogo·,·indices·:[1,1,11]},{·instrucciones·:[·SetCameraStalker - 2·],·separador·:·Sep_Evento·,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - RELOJ&MAPA·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·HoldPause - 0·,·SetGameplayCycleStalker - 1·],·separador·:·Sep_Evento·,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - INFORME·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·SetCameraStalker - 1·],·separador·:·Sep_Evento·,·indices·:[]},{·instrucciones·:[·SetCameraStalker - 2·],·separador·:·Sep_Evento·,·indices·:[]},{·instrucciones·:[·ExternalCall - check_query_mode·,·EmpezarDialogo - OBJETIVO·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·ExternalCall - change_query_mode·,·EmpezarDialogo - RESOLVER·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·SetGameplayCycleStalker - 2·,·PauseBeforeNextCycle·],·separador·:·Sep_Evento·,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - FIN_CASO·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·HoldPause - 0·],·separador·:··,·indices·:[]}],·meta·:{·independiente·:true}},·dialogueDataBaseFile·:[{·Dialogo·:·Muy buenas, <val[nick]> ¿No?·,·Efectos·:·Cambio Perfil=(Capi neutro), Oscurecer=(true), Otro Efecto=(fix_state true)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Bienvenido al <#0000FF>Centro de Seguridad Espacial<#FFFFFF>,·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·somos una agencia de inteligencia privada centrada en prestar nuestros recursos a cualquiera,·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·desde una corporación,·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·hasta a tu vecino el del quinto.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Aunque imagino que eso ya lo sabías,·,·Efectos·:·Cambio Perfil=(Capi neutro2)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·sino no hubieses aceptado este puesto de trabajo…·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Pero ya me entiendes, formalidades.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·En fin, deberás usar tu habilidad con las bases de datos y tu astucia para resolver los casos de nuestros clientes.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Por supuesto ofrecemos una serie de <#0000FF>herramientas<#FFFFFF> en tu oficina que te ayudarán en el trabajo.·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·¿Quieres que te explique el funcionamiento de las <#0000FF>herramientas<#FFFFFF>?·,·Efectos·:·Dar Opciones=(Sí @ tuto_si | Sí porfa… @ tuto_si | No hace falta @ tuto_no)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Está bien, te dejo a lo tuyo entonces.·,·Efectos·:·Otro Efecto=(fix_state false)·,·Grupo·:·INTRO·,·Etiqueta·:·tuto_no·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Muy bien, empecemos acercándonos al escritorio.·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·INTRO·,·Etiqueta·:·tuto_si·},{·Dialogo·:·Puedes moverte presionando <#0000FF>W<#FFFFFF> y <#0000FF>A<#FFFFFF>, o girando la <#0000FF>rueda del ratón<#FFFFFF>.·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·También puedes usar los botones <#FFFF00>amarillos<#FFFFFF> que hay arriba a la izquierda.·,·Efectos·:·Otro Efecto=(fix_state false)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Muy bien, ahora…·,·Efectos·:·Cambio Perfil=(Capi contento), Otro Efecto=(fix_state true)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·¿Ves este cacharro? Como podrás intuir, es un cronómetro.·,·Efectos·:·Cambio Perfil=(Capi neutro), Otro Efecto=(focus 0)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Se activa automáticamente al empezar un caso, aunque no hay límite de tiempo mientras consigas resolverlo en el mismo día…·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Ya sabes, los jefes de la empresa dicen que hay que fomentar la competitividad entre trabajadores,·,·Efectos·:·Cambio Perfil=(Capi neutro2)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·y cuanto más <i>rápido</i> y <i>mejor</i> resuelvas un caso, más alto aparecerás elas listas de puntuaciones…·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Luego, por aquí arriba tenemos 2 elementos importantes. El indicador de <#0000FF>agentes<#FFFFFF>, y el mapa.·,·Efectos·:·Cambio Perfil=(Capi neutro), Otro Efecto=(cam 3)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Los agentes son los que se encargan de reunir información y datos clave que necesitarás para resolver el caso.·,·Efectos·:·Otro Efecto=(focus 6)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Si en algún momento te quedas sin agentes, los jefes te van a <#FF0000>despedir<#FFFFFF>.·,·Efectos·:·Cambio Perfil=(Capi neutro2)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Siento sonar tan duro pero los agentes son un cuerpo voluntario, ellos eligen si ayudarte o no.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Por lo general, resolver casos con éxito hará que la fama de la agencia aumente,·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·consiguiendo nuevos agentes voluntarios en el proceso.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Pero ten cuidado <val[nick]>, <b>no todo tipo de fama va a atraer voluntarios</b>,·,·Efectos·:·Cambio Perfil=(Capi sus), Oscurecer=(true)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·puedes hacerte una idea de lo que vas a conseguir al terminar un caso en la tabla de recompensas cuando selecciones un caso.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Por otra parte, resolver casos exitosamente también podrá hacer que otras corporaciones presten sus recursos·,·Efectos·:·Cambio Perfil=(Capi neutro2), Oscurecer=(false)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·consiguiendo mejoras para nuestros servidores.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Ahora bien, la pantalla central es el mapa donde aparecerán los casos que puedes resolver.·,·Efectos·:·Cambio Perfil=(Capi neutro), Otro Efecto=(cam 3)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Estos casos son peticiones, algunas de ciudadanos, otras de empresas.·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Los <#00FF00>verdes<#FFFFFF> rectangulares son importantes y deben de resolverse,·,·Efectos·:·Mostrar Imagen=(CasoPrincipal)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·los <#FFFF00>amarillos<#FFFFFF> redondos son opcionales,·,·Efectos·:·Mostrar Imagen=(CasoSecundario)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·y de vez ecuando aparecerán iconos <#FF0000>rojos<#FFFFFF> triangulares,·,·Efectos·:·Mostrar Imagen=(CasoExamen)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·estos son casos críticos que deben solucionarse cuanto antes.·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·Para mandar agentes a hacer el informe de un caso simplemente selecciona el icono y luego pulsa el botón de solicitar,·,·Efectos·:·Mostrar Imagen=()·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·el número al lado del icono, es el número de agentes recomendado para recabar información,·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·si no tienes los agentes suficientes no podrás pedir el caso en ese momento.·,·Efectos·:··,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:·¡Solicita el caso de prueba que aparece en la pantalla del mapa!·,·Efectos·:·Cambio Perfil=(Capi contento), Otro Efecto=(fix_state false)·,·Grupo·:·RELOJ&MAPA·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Perfecto <val[nick]>, ahora para leer los detalles del informe debes abrir la carpeta que hay en el <#0000FF>cajón de informes<#FFFFFF>.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·INFORME·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·En este caso el supuesto cliente nos pide descubrir el nombre y apellidos del culpable,·,·Efectos·:·Cambio Perfil=(Capi neutro), Otro Efecto=(cam 3), Otro Efecto=(fix_state true)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·y nosotros debemos enviar a la central la <#0000FF>consulta a la base de datos<#FFFFFF> que tenga como resultado al culpable.·,·Efectos·:·Otro Efecto=(cam 2)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Ya la central se encargará de hacer el papeleo y contactar con los medios legales necesarios para cerrar el caso.·,·Efectos·:·Cambio Perfil=(Capi neutro2)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Hay un pero…·,·Efectos·:·Cambio Perfil=(Capi sus)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Al día se hacen muchas consultas a la base de datos. Contabilidad dice que hay que mitigar gastos,·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·lo que se traduce en que todos los empleados tienen un límite de consultas que pueden hacer al día.·,·Efectos·:·Otro Efecto=(focus 7)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Aquí está lo gracioso… ¡No saben que hay un bug que no cuenta las consultas que se hacen fuera de un caso!·,·Efectos·:·Cambio Perfil=(Capi sus)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Así que puedes explorar la base de datos tranquilamente mientras no estés intentando resolver un caso.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Pero si el contador llega a 0 durante un caso, me temo que tendrás que dejarle el caso a otra persona,·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·además tu día de trabajo terminará, lo cual no es bueno para ti porque te pagamos por caso resuelto…·,·Efectos·:·Cambio Perfil=(Capi sus), Ramificar=(modo_consulta)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Por cierto... me he dado cuenta de que tienes el modo <b>Consulta Manual</b> activado.·,·Efectos·:·Cambio Perfil=(Capi sus), Otro Efecto=(cam 2)·,·Grupo·:·OBJETIVO·,·Etiqueta·:·preguntar_modo·},{·Dialogo·:·Este modo de crear consultas es más rápido que mediante bloques pero también es más difícil de dominar…·,·Efectos·:··,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:·Sólo lo recomiendo si ya tienes experiencia construyendo consultas. ¿Quieres dejarlo así?·,·Efectos·:·Cambio Perfil=(Capi neutro), Dar Opciones=(Déjalo tal cual, yo controlo @ p_si | Voy a probar mejor eso de los bloques… @ p_no)·,·Grupo·:·OBJETIVO·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Muy bien.·,·Efectos·:·Establecer Evento=(modo_consulta:modo_manual)·,·Grupo·:·OBJETIVO·,·Etiqueta·:·p_si·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Muy bien.·,·Efectos·:·Establecer Evento=(modo_consulta:modo_bloque)·,·Grupo·:·OBJETIVO·,·Etiqueta·:·p_no·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·¿Y cómo creo las consultas? Te preguntarás,·,·Efectos·:·Cambio Perfil=(Capi contento), Ramificar=(modo_consulta)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·pues en este modo poco tengo que decirte, selecciona la pantalla para acercarte y poder escribir.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·RESOLVER·,·Etiqueta·:·modo_manual·},{·Dialogo·:·Saldrá un listado de palabras parecidas a la que escribes, si presionas TAB, se va a autocompletar con la primera palabra de la lista.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·Cuando termines de escribir la consulta selecciona el botón OK.·,·Efectos·:·Ir A Entrada=(tuto_consulta_listo)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·<#0000FF>Conectando<#FFFFFF> bloques, claro.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·RESOLVER·,·Etiqueta·:·modo_bloque·},{·Dialogo·:·Puedes generar todos los bloques que veas necesarios usando la <#0000FF>tableta<#FFFFFF> que tienes a tu derecha.·,·Efectos·:·Cambio Perfil=(Capi neutro)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·Una vez hayas construido la consulta debes <#0000FF>fusionarla<#FFFFFF> en un único bloque,·,·Efectos·:··,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·para hacer eso arrastra los bloques unidos al <#0000FF>agrupador de bloques<#FFFFFF>, la máquina que hay al fondo a la izquierda.·,·Efectos·:·Otro Efecto=(focus 1)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·Por último colocas el bloque resultante en el <#0000FF>Socket<#FFFFFF> del centro.·,·Efectos·:·Otro Efecto=(focus 2),Ir A Entrada=(tuto_consulta_listo)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·¡Y listo! Consulta preparada.·,·Efectos·:·Otro Efecto=(cam 2)·,·Grupo·:·RESOLVER·,·Etiqueta·:·tuto_consulta_listo·},{·Dialogo·:·Para enviar la consulta puedes pulsar el botón rojo central y te mostrará el resultado de esta,·,·Efectos·:·Otro Efecto=(focus 4)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·si crees que tu consulta es la correcta, pulsa el botón rojo de la izquierda y se enviará a la central directamente.·,·Efectos·:·Otro Efecto=(focus 3)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·Si ves que no vas a poder resolver el caso puedes rendirte dándole al botón rojo de la derecha para poder intentar otro caso distinto.·,·Efectos·:·Cambio Perfil=(Capi neutro2), Otro Efecto=(focus 5)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:·Te invito a que intentes resolverlo.·,·Efectos·:·Cambio Perfil=(Capi contento), Otro Efecto=(cam 2), Otro Efecto=(fix_state false)·,·Grupo·:·RESOLVER·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·¿Ya has terminado?·,·Efectos·:·Cambio Perfil=(Capi neutro), Otro Efecto=(fix_state true), Ramificar=(win_condition)·,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:·Perfecto <val[nick]>. Diría que ya estás listo para empezar.·,·Efectos·:·Cambio Perfil=(Capi contento), Ir A Entrada=(tuto_fin)·,·Grupo·:·FIN_CASO·,·Etiqueta·:·win·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Vaya…·,·Efectos·:·Cambio Perfil=(Capi sus)·,·Grupo·:·FIN_CASO·,·Etiqueta·:·lose·},{·Dialogo·:·Bueno, no pasa nada <val[nick]>, ya te irás acostumbrando.·,·Efectos·:·Cambio Perfil=(Capi neutro2), Ir A Entrada=(tuto_fin)·,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·¿En serio <val[nick]>?·,·Efectos·:·Cambio Perfil=(Capi sus)·,·Grupo·:·FIN_CASO·,·Etiqueta·:·surrender·},{·Dialogo·:·¿Te has rendido en el tutorial?·,·Efectos·:··,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:·No te recomiendo rendirte muy a menudo. Si no completas casos que has aceptado…·,·Efectos·:·Cambio Perfil=(Capi neutro2)·,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:·puede que el cliente se enfade, o que recibas algún tipo de…·,·Efectos·:··,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:·<#FF0000>PENALIZACIÓN<#FFFFFF>·,·Efectos·:·Ir A Entrada=(tuto_fin)·,·Grupo·:·FIN_CASO·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:·Ramificar=(modo_consulta)·,·Grupo·:·FIN_CASO·,·Etiqueta·:·tuto_fin·},{·Dialogo·:·Como consejo extra, si quieres quitar bloques para despejar la mesa, puedes arrastrarlos fuera de esta.·,·Efectos·:·Cambio Perfil=(Capi contento)·,·Grupo·:·FIN_CASO·,·Etiqueta·:·modo_bloque·},{·Dialogo·:·Y poco más. Espero que disfrutes este trabajo tanto como lo hice yo en el pasado, en fin.·,·Efectos·:··,·Grupo·:·FIN_CASO·,·Etiqueta·:·modo_manual·},{·Dialogo·:·¡Ya nos veremos en unos días!·,·Efectos·:·Otro Efecto=(fix_state false)·,·Grupo·:·FIN_CASO·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(1, '{·id·:1,·titulo·:·Noticiap2d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·DIA_ACTUAL = 1·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - NOTICIA·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - FIN·,·IncluirCaso - 2·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Antes de comenzar tu trabajo, lees las noticias de la mañana.·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·Todo está como siempre ha estado, lleno de relleno, artículos superficiales, y cada titular más exagerado que el anterior para robar tu atención.·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·De entre toda la maraña de noticias, hay una que sale de la norma y decides leerla.·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'El infame grupo de hermanas corgo conocidas por traficar droga sintética, sufrió un ataque esta noche, 2 días antes de su juicio.\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'Sólo una de ellas queda viva, la cual pide ayuda y ha anunciado por todos los medios que se vengará de una forma u otra\'...·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·¿Para qué querrían matar a alguien cuya sentencia es cadena perpetua? ¿Son héroes por asesinar delincuentes, o es igual de malo? ¿Importa tu vida si estás condenado a cadena perpetua?·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Sea cual sea la respuesta, has incluido tú mismo este misterio en el mapa. Ya te pararás luego a pensar si vale la pena resolverlo o no.·,·Efectos·:··,·Grupo·:·FIN·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(2, '{·id·:2,·titulo·:·Casos2d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·DIA_ACTUAL = 1·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·IncluirCaso - 101·],·separador·:··,·indices·:[]}]},·dialogueDataBaseFile·:[],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(3, '{·id·:3,·titulo·:·Casos1d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·DIA_ACTUAL = 2·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - INTRO·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - MADRE·],·separador·:·Fin Dialogo·,·indices·:[]},{·instrucciones·:[·IncluirCaso - 100·],·separador·:··,·indices·:[]},{·instrucciones·:[·EmpezarDialogo - KRIPO·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Oyes cómo un llanto distante está acercándose a tu puerta.·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·No es el típico llanto de oficinista al borde de la locura que has llegado a escuchar en tus trabajos anteriores, este más bien suena como el de un niño...·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·La puerta de tu oficina se abre de golpe, dejando ver un pequeño feriseo de unos 8 años, sin supervisión alguna.·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·¡Agente del CSE! ¡Agente del CSE! ¡Ayúdeme porfaaaaa!·,·Efectos·:·Cambio Perfil=(Imp triste1), Oscurecer=(false)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Parece estar bastante alterado...·,·Efectos·:·Cambio Perfil=(), Dar Opciones=(Claro pequeñín, cuéntame ¿Qué te ocurre? @ rollazo | ¿¿¿Cómo te has saltado toda la seguridad??? @ seguridad)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Mi mamá simpre me dice que soy tan escurridizo como un veliposo (especie autóctona de su planeta parecida a la anguila)·,·Efectos·:·Cambio Perfil=(Imp neutro)·,·Grupo·:·INTRO·,·Etiqueta·:·seguridad·},{·Dialogo·:·Y-yo hoy bajé al sótano a coger un juguete que quería enseñar a mis amigos que estaban en mi casa porque es mi cumple y yo les había invitado,·,·Efectos·:·Cambio Perfil=(Imp triste1)·,·Grupo·:·INTRO·,·Etiqueta·:·rollazo·},{·Dialogo·:·¡Y vi un hombre malo pegando a mi papá! ¡Y vine aquí porque el CSE son muy buenos!·,·Efectos·:·Cambio Perfil=(Imp triste2)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·Le decía palabras feas porque mi papá no quería llevarles mañana en coche al puerto de naves para recoger colas…·,·Efectos·:·Cambio Perfil=(Imp triste1)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·A lo mejor le pega porque mi papá mentía, decía que ya no trabajaba en eso pero mi papá sí que lleva en coche a la gente, lo sé porque me lleva en coche al cole todos los días.·,·Efectos·:··,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·PERO EL HOMBRE MALO NO DEJABA DE DECIRLE COSAS MALAS Y QUE LE HARÍA DAÑO SI NO LO HACÍA PORQUE HAY MUCHO JUGO.·,·Efectos·:·Cambio Perfil=(Imp triste3)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·El hombre malo pagaba a mi papá, pero mi papá es muy bueno, y no hace falta ir al puerto a comprar cola,·,·Efectos·:·Cambio Perfil=(Imp triste1)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·¡Se puede comprar refrescos en la tienda del parque!·,·Efectos·:·Cambio Perfil=(Imp triste2)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Cambio Perfil=(), Dar Opciones=(¿Pudiste escuchar a qué parte del puerto querían que condujese tu padre? @ cont)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·No sé... El hombre malo dijo que iban a esperar la nave de Nidolé.·,·Efectos·:·Cambio Perfil=(Imp triste1)·,·Grupo·:·INTRO·,·Etiqueta·:·cont·},{·Dialogo·:·...·,·Efectos·:·Cambio Perfil=(), Dar Opciones=(Muy bien, haré todo lo posible para ayudar a tu papá @ ayuda | Ya veré si puedo hacer algo... @ noayuda)·,·Grupo·:·INTRO·,·Etiqueta·:··},{·Dialogo·:·¿De vedad? ¡Muchas gracias agente!·,·Efectos·:·Cambio Perfil=(Imp triste1),Establecer Evento=(promesa_imp:1)·,·Grupo·:·INTRO·,·Etiqueta·:·ayuda·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Entiendo agente, seguro que estará muy ocupado ayudando a otros papás...·,·Efectos·:·Cambio Perfil=(Imp triste1)·,·Grupo·:·INTRO·,·Etiqueta·:·noayuda·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·A todo esto, aparece una mujer ferisea, tiene pinta de ser la madre.·,·Efectos·:·Cambio Perfil=(),Oscurecer=(true)·,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Está visiblemente cansada, jadeando por la falta de aire, pero su preocupación parece haberle dado las energías para perseguir a su hijo.·,·Efectos·:··,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·¡Ven aquí niño!·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Ay... disculpe... por mi hijo...·,·Efectos·:··,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·No parece tener aire para decir ni una frase entera·,·Efectos·:·Oscurecer=(true),Cambio Perfil=()·,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Siento... haberle molestado... mientras... está trabajando. (Se recompone)·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Ay, siento haberle molestado, el niño no sabe lo que está diciendo. ¡Vamos a casa, venga!·,·Efectos·:··,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Antes de que pueda decir algo, la mujer cerró la puerta y se fue con su hijo...·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:·Por si acaso debería indicarle el número del puerto a la policía para que tomen medidas mañana...·,·Efectos·:··,·Grupo·:·MADRE·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Antes de volver a mi cómoda paz solitaria, alguien más vuelve a abrir la puerta.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·¡Hola buenas! Tú debes de ser <val[nick]> ¿No?·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Encantado yo soy <#ffff00>Kripo</color>. Estoy aquí como voluntario y me encargo un poco del papeleo y de recibir a la gente que pide ayuda.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Siento que te hayan molestado antes...·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·¡Tanto el niño como la madre pasaron de mi completamente!·,·Efectos·:·Cambio Perfil=(Kripo enfadado)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Pero bueno, justo cuando se fueron me llegó una notificación sobre el caso que acabas de incluir,·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·quería comentarte que no tienes acceso a la tabla de transbordos...·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·¡Pero no pasa nada!·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Yo me encargo de mandar la solicitud para el acceso a la tabla,·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·una vez desbloquees el acceso, lo tendrás para siempre y podrás utilizar la tabla para futuros casos si te hace falta.·,·Efectos·:·Cambio Perfil=(Kripo contento)·,·Grupo·:·KRIPO·,·Etiqueta·:··}],·tableCodesNuevos·:·transbordos·,·modVarGameplay·:··}\r'),
(4, '{·id·:4,·titulo·:·NoticiaPostp2d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·AND(OR(CASO_PERDIDO=2,CASO_ABANDONADO=2),DIA_ACTUAL>3)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - NOTICIA·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Una de las noticias destacadas de hoy...·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·La última de las hermanas traficantes yace hoy muerta tras sufrir un accidente durante una de sus tareas en la cárcel.·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·Tras investigar el lugar del accidente, ninguna compañera reclusa ha estado presente durante lo ocurrido.·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:·Oscurecer=(false)·,·Grupo·:·NOTICIA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(5, '{·id·:5,·titulo·:·casopEd1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·OR(CASO_COMPLETADO=2,CASO_PERDIDO=2,CASO_ABANDONADO=2)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·IncluirCaso - 3·],·separador·:··,·indices·:[]}]},·dialogueDataBaseFile·:[],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(6, '{·id·:6,·titulo·:·NoticiaPosts1d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·AND(CASO_COMPLETADO=100,EVENTO_PROMESA_IMP=1,DIA_ACTUAL>3)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - NOTICIA·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Una de las noticias destacadas de la mañana habla sobre el CSE...·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'El CSE lo ha vuelto a hacer, han atrapado una banda de delincuentes antes de que estos realicen el propio crímen...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... al parecer, estaban amenazando a una familia la cual tuvo el valor de denunciar el problema...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... los agentes del CSE siempre cumplen sus promesas, dijo el miembro menor de esta familia de feriseos...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... ante todo esto, la mega-corporación Nidolé sigue en silencio.\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·El niño feriseo de la foto en la noticia te resulta familiar.·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·NOTICIA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:·RP+5·}\r'),
(7, '{·id·:7,·titulo·:·PostCasopEd1·,·diario·:false,·momentoComprobable·:2,·condicionUnparsed·:·CASO_COMPLETADO = 3·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·SetDialogueEvent - nft = ok·],·separador·:··,·indices·:[]}]},·dialogueDataBaseFile·:[],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(8, '{·id·:8,·titulo·:·NoticiaPostpEd1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·OR(CASO_COMPLETADO=3,CASO_PERDIDO=3,CASO_ABANDONADO=3)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - NOTICIA·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Antes de empezar tu trabajo, miras tu dispositivo...·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·Una notificación aparece en pantalla de una noticia sobre la empresa a la que hackearon recientemente.·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·Decides ojear la noticia rápidamente.·,·Efectos·:·Oscurecer=(false),Ramificar=(nft)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'La compañía tuvo que pagar el rescate de los datos biométricos bajo la presión del gobierno y las leyes de protección de datos...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... por desgracia no pudieron descubrir información sobre el hacker, ...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... aún así, el CEO de la empresa ha asegurado que tiene pruebas de que el hacker es un exukente.\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·\'El CSE colaboró con la empresa para descubrir la identidad del hacker.\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:·ok·},{·Dialogo·:·\'... dicho individuo resultó ser de la especie exukente...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'... esto no es nada bueno para la imagen de los exukentes, que cada vez están más presentes en...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·No va a ser muy cómodo hablar de este tema con <#ffff00>Kripo</color>, el exukente que trabaja aquí...·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(9, '{·id·:9,·titulo·:·InicioDif2·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·OR(CASO_COMPLETADO=3,CASO_PERDIDO=3,CASO_ABANDONADO=3)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·IncluirCaso - 4·,·EmpezarDialogo - WORBULO·],·separador·:··,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Alguien llama a la puerta de tu oficina educadamente (en vez de abrirla sin avisar porque la gente no tiene modales aquí).·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Buenos días, me llamo Worbulo, me encargo del mantenimiento de la infraestructura y redes del CSE. Tú debes de ser <val[nick]>, ¿No?·,·Efectos·:·Oscurecer=(true), Cambio Perfil=(Worbulo neutro)·,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Me ha llegado un aivso sobre el caso especial que resolviste ayer,·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·así que vengo a comentarte los cambios en el sistema tras completar dicho caso.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Lo primero de todo es que ahora podrás hacer consultas más complejas,·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·concretamente ahora puedes usar Keywords como \'Order by\' que ordena la consulta según los valores de la columna indicada, y \'Like\' que permite comparar patrones de cadenas.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Hay más cosas pero tu escritorio ya debería de estar actualizado, échale un vistazo tú mismo.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·También gracias al reciente acuerdo con un par de empresas ahora tenemos más tablas a nuestra disposición.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Concretamente las empresas particulares Murica Guns, Corgomatic, y Mega Milky nos han compartido sus datos como forma de dar las gracias por nuestro trabajo.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Y eso es todo. A, por cierto, mi nombre es Worbulo, que se me ha olvidado presentarme.·,·Efectos·:··,·Grupo·:·WORBULO·,·Etiqueta·:··},{·Dialogo·:·Espero saber más noticias buenas sobre tí. <i>Corulm</i> (Despedida común de los Corgos).·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·WORBULO·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r'),
(10, '{·id·:10,·titulo·:·NoticiasPosts2d1·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·AND(CASO_COMPLETADO=101, DIA_ACTUAL>2)·,·probabilidad·:50,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - NOTICIA·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Entre una de las noticias de esta mañana, te encuentras con el siguiente titular:·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'Ha habido un aumento de robos en los domicilios cercanos a las calles Reina Forilisia y Giripimbas 3º...\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·\'De alguna forma los ladrones actuaron justo cuando sabían que no había nadie en casa.\'·,·Efectos·:··,·Grupo·:·NOTICIA·,·Etiqueta·:··},{·Dialogo·:·Esas calles... resultan familiares...·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·NOTICIA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}\r');

-- --------------------------------------------------------

--
-- Estructura para la tabla `learningRecord`
--

CREATE TABLE `learningRecord` (
  `recordID` int NOT NULL,
  `actor` text NOT NULL COMMENT 'The player for whom the statement is made',
  `verb` text NOT NULL COMMENT 'the action that triggered the statement',
  `object` text NOT NULL COMMENT 'the object the player have manipulated/ is relevant to the action',
  `result` text COMMENT 'data produced after the action',
  `context` text COMMENT 'data related to the action',
  `timestamp` datetime DEFAULT NULL COMMENT 'the moment the statement was created (not when it was sent)',
  `whole_statement` text NOT NULL COMMENT 'the raw complete statement, for redundancy reasons'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `players`
--

CREATE TABLE `players` (
  `id` int NOT NULL,
  `email` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `nickname` varchar(50) NOT NULL,
  `password` varchar(50) NOT NULL,
  `fechaCreacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `savedfiles`
--

CREATE TABLE `savedfiles` (
  `id` int NOT NULL,
  `file` json DEFAULT NULL,
  `player_id` int NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `scores`
--

CREATE TABLE `scores` (
  `id` int NOT NULL,
  `player_id` int NOT NULL,
  `case_id` int DEFAULT NULL,
  `difficulty` int UNSIGNED NOT NULL,
  `score` int NOT NULL,
  `used_queries` int UNSIGNED NOT NULL,
  `time_spent` float NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `tablesUnlockCode`
